RETURNS trigger
LANGUAGE plpgsql
AS $_$
BEGIN
    NEW.last_update = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$_$;
ALTER FUNCTION public.last_updated() OWNER TO "stephanie.herr@red-gate.com";


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating public.inventory_in_stock(integer)...';END$$;
CREATE FUNCTION public.inventory_in_stock(IN p_inventory_id integer)
RETURNS boolean
LANGUAGE plpgsql
AS $_$
DECLARE
    v_rentals INTEGER;
    v_out INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_rentals FROM public.rental WHERE inventory_id = p_inventory_id;
    IF v_rentals = 0 THEN
      RETURN TRUE;
    END IF;

    SELECT COUNT(*) INTO v_out FROM public.inventory, public.rental 
    WHERE inventory.inventory_id = rental.inventory_id 
      AND rental.inventory_id = p_inventory_id 
      AND rental.return_date IS NULL;

    IF v_out > 0 THEN
      RETURN FALSE;
    ELSE
      RETURN TRUE;
    END IF;
END;
$_$;
ALTER FUNCTION public.inventory_in_stock(IN p_inventory_id integer) OWNER TO "stephanie.herr@red-gate.com";


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating public.grant_usage_on_new_schema()...';END$$;
CREATE FUNCTION public.grant_usage_on_new_schema()
RETURNS event_trigger
LANGUAGE plpgsql
AS $_$
DECLARE
    db_id TEXT;
    obj record;
BEGIN
    SELECT oid FROM pg_catalog.pg_database WHERE datname = pg_catalog.current_database() INTO db_id;
    FOR obj IN (SELECT * FROM pg_catalog.pg_event_trigger_ddl_commands() AS ddl
                WHERE ddl.object_type = 'schema' AND ddl.object_identity != '__db_system')
    LOOP
        BEGIN
            EXECUTE pg_catalog.format('GRANT USAGE ON SCHEMA %s TO "databricks_gateway"', obj.object_identity);
            EXECUTE pg_catalog.format('GRANT ALL ON SCHEMA %s TO "databricks_superuser" WITH GRANT OPTION', obj.object_identity);
        EXCEPTION
            WHEN others THEN
                RAISE WARNING 'An error occurred while granting system permissions on schema %: %', obj.object_identity, SQLERRM;
        END;

        BEGIN
            EXECUTE pg_catalog.format('GRANT USAGE ON SCHEMA %s TO databricks_reader_%s', obj.object_identity, db_id);
            EXECUTE pg_catalog.format('GRANT USAGE, CREATE ON SCHEMA %s TO databricks_writer_%s', obj.object_identity, db_id);
        EXCEPTION
            WHEN others then
                RAISE WARNING 'An error occurred while granting system permissions on schema %: %', obj.object_identity, SQLERRM;
        END;
    END LOOP;
END;
$_$;
ALTER FUNCTION public.grant_usage_on_new_schema() OWNER TO cloud_admin;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating public.grant_select_on_new_objects()...';END$$;
CREATE FUNCTION public.grant_select_on_new_objects()
RETURNS event_trigger
LANGUAGE plpgsql
AS $_$
DECLARE
    db_id TEXT;
    obj record;
    schema_name TEXT;
    object_name TEXT;
BEGIN
    SELECT oid from pg_catalog.pg_database WHERE datname = pg_catalog.current_database() INTO db_id;
    FOR obj IN (SELECT * FROM pg_catalog.pg_event_trigger_ddl_commands() AS ddl
                WHERE ddl.object_type IN ('table', 'view', 'materialized view')
                AND ddl.object_identity != '__db_system')
    LOOP
        BEGIN
            EXECUTE pg_catalog.format('GRANT SELECT ON %s TO "databricks_gateway"', obj.object_identity);
            EXECUTE pg_catalog.format('GRANT ALL ON %s TO "databricks_superuser" WITH GRANT OPTION', obj.object_identity);
        EXCEPTION
            WHEN others THEN
                RAISE WARNING 'An error occurred while granting system permissions on object %: %', obj.object_identity, SQLERRM;
        END;

        BEGIN
            EXECUTE pg_catalog.format('GRANT SELECT ON %s TO databricks_reader_%s', obj.object_identity, db_id);
        EXCEPTION
            WHEN others THEN
                RAISE WARNING 'An error occurred while granting system permissions on object %: %', obj.object_identity, SQLERRM;
        END;
    END LOOP;
END;
$_$;
ALTER FUNCTION public.grant_select_on_new_objects() OWNER TO cloud_admin;


