DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating public._group_concat(text, text)...';END$$;
CREATE FUNCTION public._group_concat(IN text, IN text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $_$
SELECT CASE
  WHEN $1 IS NULL OR $1 = '' THEN $2
  WHEN $2 IS NULL OR $2 = '' THEN $1
  ELSE $1 || ', ' || $2
END;
$_$;
ALTER FUNCTION public._group_concat(IN text, IN text) OWNER TO "stephanie.herr@red-gate.com";


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating public.group_concat(text)...';END$$;
CREATE AGGREGATE public.group_concat(text) (
    SFUNC = public._group_concat,
    STYPE = text
);
ALTER AGGREGATE public.group_concat(text) OWNER TO "stephanie.herr@red-gate.com";


